        run,
        workflow,
        Box::from([(SlotIdx::ZERO, SlotValue::I64(0))]),
        action_grants(action),
        action_contracts_through(action, 1, 1),

        action_contracts_through(action, 1, 1),
    )
}

fn action_ticket(run: RunId, action: ActionId) -> ActionTicket {
